/**
 * Fixtures for the agent-principal credential tests (src/principal-store.js).
 *
 * No production path can mint a token (contract section 12 landing order), so tests
 * create principals here: a store over a TEMP directory, constructed with
 * `allowTestInsert`, and a token generated by the test. The store's own entry builder
 * validates the grant exactly as a later `grant` will.
 */
import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { randomBytes } from 'node:crypto'
import { PrincipalStore, buildPrincipalEntry, hashPrincipalToken } from '../../src/principal-store.js'

/** A fresh temp directory and its cleanup. */
export function tempPrincipalDir() {
  const dir = mkdtempSync(join(tmpdir(), 'chroxy-principals-'))
  return { dir, path: join(dir, 'principals.json'), cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

/**
 * A principal store over `path`, with a settable clock.
 * @param {string} path
 * @param {{ now?: () => number, writeDurable?: Function }} [opts]
 */
export function testPrincipalStore(path, opts = {}) {
  const store = new PrincipalStore({ path, allowTestInsert: true, ...opts })
  store.refresh()
  return store
}

/** A settable clock for the store and the server's expiry timer. */
export function fakeClock(start = 1_800_000_000_000) {
  const clock = { t: start, now: () => clock.t, advance: (ms) => { clock.t += ms; return clock.t } }
  return clock
}

/**
 * Insert one principal and return its token (the only place a token exists).
 * @param {PrincipalStore} store
 * @param {object} [over]
 * @returns {{ token: string, entry: object }}
 */
export function insertPrincipal(store, over = {}) {
  const token = over.token ?? randomBytes(24).toString('base64url')
  const built = buildPrincipalEntry({
    label: over.label ?? 'supervisor',
    scope: over.scope ?? 'answer',
    constraints: over.constraints ?? { sessionIds: ['sess-1'] },
    ttlMs: over.ttlMs,
  }, { tokenHash: hashPrincipalToken(token), principalId: over.principalId ?? 'pr-1', now: store.now() })
  if (!built.ok) throw new Error(`fixture grant refused: ${built.code}`)
  store._testOnlyInsertEntry(built.entry)
  return { token, entry: built.entry }
}
